<tool_call>
<function=bash>
<parameter=command>
cat > /tmp/assemble2.py <<'PYEOF'
import json, yaml, re

sigma = open('/tmp/sigma.yaml').read().rstrip()

kql_raw = r"""// curl|wget -> /tmp staging -> bash execution  (T1105 Ingress Tool Transfer chained into T1059.004 Unix Shell).
// Source DeviceProcess (Linux auditd / eBPF process_creation telemetry). Field mapping is identical to the
// paired Sigma rule - ParentFileName corresponds to ParentImage and InitiatingProcessCommandLine corresponds to
// InitiatingProcessCommandLine/execline, so both artifacts express the same detection logic against this schema.
// Stage1 Downloader: FileName curl or wget performing a file write (-o or --output-document) into /tmp, /var/tmp or
//   /dev/shm using an http(s)/ftp source URL. Stage2 Executor: bash or sh invoking one of those staged paths.
// The correlation binds the stages by process lineage rather than time alone, so LauncherPid must equal DownloadPid
// (the shell was spawned by that exact curl/wget PID), parent image must be curl or wget, LaunchingCmdline must hold
// the download command carrying -o plus the extracted StagedPayload, and TimeToExecute_s must stay under 120s. Two
// equivalent chain shapes are matched from the data: bash whose InitiatingProcessCommandLine starts with curl and
// whose own CommandLine runs the same /tmp payload (pid 2231 curl -s -o /tmp/update.sh ... spawing pid 2240
// bash /tmp/update.sh about 2.2 s later), and bash executed after a second-stage downloader seeded by the first
// payload (pid 4103 wget -O /tmp/stage2 ... spawning pid 4104 bash /tmp/stage2 about 1.2 s later, still rooted in the
// stage-1 /tmp/update.sh). Because a following exec-ing child is mandatory, stage-1 downloads that are never run do
let Lookback = 7d;
let WindowS = 120;
let Downloader = DeviceProcess
| where Timestamp > ago(Lookback)
| where FileName in~ ("curl", "wget")
| where CommandLine contains "/tmp/" or CommandLine contains "/var/tmp/" or CommandLine contains "/dev/shm/"
| where CommandLine contains "-o" or CommandLine contains "--output-document"
| where CommandLine contains "http://" or CommandLine contains "https://" or CommandLine contains "ftp://"
| extend DeviceName = lower(DeviceId), DownloadPid = toint(ProcessId), DownloadTime = Timestamp, User = AccountName,
         StagedPayload = tolower(extract(@"(/[a-zA-Z0-9_./-]*?(?:tmp|shim)[a-zA-Z0-9_.-]*)", 1, CommandLine))
| project DeviceName, DownloadPid, DownloadTime, StagedPayload, DownloadImage = FileName, Download_Cmdline = CommandLine, User;
let Executor = DeviceProcess
| where Timestamp > ago(Lookback)
| where FileName in~ ("bash", "sh")
| where CommandLine contains "/tmp/" or CommandLine contains "/var/tmp/" or CommandLine contains "/dev/shm/"
| extend DeviceName = lower(DeviceId), ExecPid = toint(ProcessId), ExecTime = Timestamp,
         ParentImage = ParentFileName, LauncherPid = toint(InitiatingProcessId), LaunchingCmdline = InitiatingProcessCommandLine, ExecUser = AccountName
| project DeviceName, ExecPid, ExecTime, ParentImage, LauncherPid, LaunchingCmdline, Execution_CMDLINE = CommandLine, ExecUser;
Downloader
| join kind=inner Executor on DeviceName
| where LauncherPid == DownloadPid
| where ParentImage in~ ("curl", "wget") or LaunchingCmdline startswith "curl " or LaunchingCmdline startswith "wget "
| where datetime_diff("second", ExecTime, DownloadTime) between (int64(0) .. int64(WindowS))
| project StartTime = min_todatetime(coalesce(DownloadTime, ExecTime)), AlertTime = max_todatetime(ExecTime), EndTime = format_datetime(max_todatetime(ExecTime), "yyyy-MM-ddTHH:mm:ssZ"), """ + r''""""

def protect_backslash(s):
    # any backslash would have to be double-escaped for JSON; eliminate them instead
    return s.replace("\\", "\\")  # placeholder guard (no backslashes expected)

print("has backslash:", "\\" in kql_raw)
# find leftover broken tokens
for tok in ["min_todatetime","max_todatetime","format_datetime(","\"\"\""]:
    if tok in kql_raw: print("BAD TOKEN PRESENT:", tok)
open('/tmp/kql_draft.txt','w').write(kql_raw)
PYEOF
python3 /tmp/assemble2.py
</parameter>
